use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (out: Vec<i32>)
    ensures
        out@.len() == a@.len() + b@.len(),
        forall|i: int|
            0 <= i < a@.len() ==> out@[i] == a@[i],
        forall|j: int|
            0 <= j < b@.len() ==> out@[a@.len() + j] == b@[j],
{
    let mut out: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            out@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> out@[k] == a@[k],
        decreases a.len() - i,
    {
        out.push(a[i]);
        i = i + 1;
    }

    let a_len = a.len();
    let mut j: usize = 0;
    while j < b.len()
        invariant
            out@.len() == a_len as int + j as int,
            forall|k: int| 0 <= k < a_len as int ==> out@[k] == a@[k],
            forall|t: int| 0 <= t < j as int ==> out@[a_len as int + t] == b@[t],
        decreases b.len() - j,
    {
        out.push(b[j]);
        j = j + 1;
    }

    out
}

} // verus!

